"""Script per testare la nuova azione SearchRole per cercare un ruolo specifico."""

import requests
import json
import os
import sys

# Fail before any request if protected test credentials are missing.
CLIENT_ID = os.environ["XSUAA_CLIENT_ID"]
CLIENT_SECRET = os.environ["XSUAA_CLIENT_SECRET"]

XSUAA_URL = "https://dev-datasphere-gcp.authentication.eu30.hana.ondemand.com/oauth/token"
SERVICE_URL = "https://acea-dev-datasphere-gcp-dev-dsp-scim-handler-srv.cfapps.eu30.hana.ondemand.com"


def get_oauth_token():
    """Ottiene un token OAuth2 senza registrare token o risposte di autenticazione."""
    if not CLIENT_ID or not CLIENT_SECRET:
        print("Impostare XSUAA_CLIENT_ID e XSUAA_CLIENT_SECRET nell'ambiente.")
        return None
    print(f"🔐 Richiesta token a: {XSUAA_URL}")

    try:
        response = requests.post(
            XSUAA_URL,
            data={
                "grant_type": "client_credentials",
                "client_id": CLIENT_ID,
                "client_secret": CLIENT_SECRET
            },
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            timeout=10
        )
        print(f"   Status: {response.status_code}")
        if response.status_code == 200:
            token_data = response.json()
            print("   ✅ Token ottenuto!")
            return token_data.get("access_token")
        print(f"   ❌ Autenticazione fallita: HTTP {response.status_code}")
        return None
    except Exception:
        print("   ❌ Richiesta di autenticazione non riuscita")
        return None


def call_search_role(token, role_value):
    """Chiama l'azione SearchRole sul servizio CAP."""
    url = f"{SERVICE_URL}/data/SearchRole"
    print(f"\n🔍 Ricerca ruolo: {role_value}")
    print(f"🌐 Endpoint: {url}\n")

    try:
        response = requests.post(
            url,
            headers={
                "Authorization": f"Bearer {token}",
                "Accept": "application/json",
                "Content-Type": "application/json"
            },
            json={"roleValue": role_value},
            timeout=30
        )

        print(f"   Status: {response.status_code}")
        if response.status_code in [200, 201]:
            data = response.json()
            print("\n✅ Risposta ricevuta:")
            print(json.dumps(data, indent=2, ensure_ascii=False))

            if data.get('exists'):
                print(f"\n🎉 Ruolo TROVATO: '{role_value}'")
                users = data.get('found_in_users', [])
                if users:
                    print(f"\n👥 Trovato in {len(users)} utente(i):")
                    for u in users:
                        print(f"   - {u.get('userName', 'N/A')} ({u.get('displayName', 'N/A')})")
            else:
                print(f"\n❌ Ruolo NON TROVATO: '{role_value}'")
                print("   Il ruolo non è assegnato a nessun utente attivo nell'API SCIM")
        else:
            print(f"   ❌ Errore: {response.status_code}")
            print(f"   Body: {response.text[:500]}")
        return response
    except Exception as e:
        print(f"   ❌ Eccezione: {e}")
        return None


def main():
    """Esegue la ricerca del ruolo indicato dopo l'autenticazione."""
    if len(sys.argv) > 1:
        role_to_search = sys.argv[1]
    else:
        role_to_search = "BW_C_IT_0170_AEEN_COCGU"

    print("=" * 70)
    print("TEST RICERCA RUOLO - CAP SCIM Handler Service")
    print("=" * 70)

    token = get_oauth_token()
    if not token:
        print("\n❌ Impossibile ottenere token - test fallito")
        sys.exit(1)

    call_search_role(token, role_to_search)
    print("\n" + "=" * 70)


if __name__ == "__main__":
    main()